package com.scanny.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.time.Instant;

/**
 * A reminder or chaser notification row generated by the daily scheduler.
 *
 * <p>Rows are written <em>before</em> anything is dispatched; the
 * {@link com.scanny.rent.notification.NotificationSender} is invoked
 * afterwards.  This means:
 * <ul>
 *   <li>The notification audit trail survives even if delivery fails.</li>
 *   <li>A future delivery worker can retry rows whose {@code sentAt} is null.</li>
 *   <li>De-duplication is enforced by the {@code UNIQUE (charge_id, event_type)}
 *       constraint so re-running the scheduler never double-notifies.</li>
 * </ul>
 *
 * <h3>event_type values</h3>
 * <ul>
 *   <li>{@code UPCOMING_3D}  — 3 days before due date</li>
 *   <li>{@code OVERDUE_1D}   — 1 day after due date</li>
 *   <li>{@code OVERDUE_3D}   — 3 days after due date</li>
 *   <li>{@code OVERDUE_7D}   — 7 days after due date</li>
 * </ul>
 */
@Entity
@Table(name = "rent_notifications")
public class RentNotification {

    @Id
    @Column(length = 36)
    private String id;

    /** The charge this notification relates to. */
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "charge_id", nullable = false)
    private RentCharge charge;

    /**
     * Logical event that triggered this notification.
     * One of: {@code UPCOMING_3D}, {@code OVERDUE_1D}, {@code OVERDUE_3D}, {@code OVERDUE_7D}.
     */
    @Column(name = "event_type", nullable = false, length = 32)
    private String eventType;

    /** Delivery channel — currently always {@code WHATSAPP}. */
    @Column(nullable = false, length = 32)
    private String channel = "WHATSAPP";

    /** Normalised phone number or email of the recipient. */
    @Column(nullable = false, length = 64)
    private String recipient;

    /** Full message body that would be / was sent. */
    @Column(columnDefinition = "TEXT", nullable = false)
    private String body;

    /** When this row was created by the scheduler. */
    @Column(name = "created_at", nullable = false)
    private Instant createdAt = Instant.now();

    /** When the message was actually dispatched. Null = not yet sent. */
    @Column(name = "sent_at")
    private Instant sentAt;

    /**
     * Identifies the account (manager) under whom this property sits.
     * Stored as a plain string so the notification row survives account deletion.
     */
    @Column(name = "created_by", length = 64)
    private String createdBy = "scheduler";

    // ── Getters / setters ─────────────────────────────────────────────────────

    public String getId()                    { return id; }
    public void setId(String id)             { this.id = id; }

    public RentCharge getCharge()            { return charge; }
    public void setCharge(RentCharge c)      { this.charge = c; }

    public String getEventType()             { return eventType; }
    public void setEventType(String t)       { this.eventType = t; }

    public String getChannel()               { return channel; }
    public void setChannel(String c)         { this.channel = c; }

    public String getRecipient()             { return recipient; }
    public void setRecipient(String r)       { this.recipient = r; }

    public String getBody()                  { return body; }
    public void setBody(String b)            { this.body = b; }

    public Instant getCreatedAt()            { return createdAt; }
    public void setCreatedAt(Instant t)      { this.createdAt = t; }

    public Instant getSentAt()               { return sentAt; }
    public void setSentAt(Instant t)         { this.sentAt = t; }

    public String getCreatedBy()             { return createdBy; }
    public void setCreatedBy(String by)      { this.createdBy = by; }
}
